    "title": "Cereal Cash Candles",
    "description": "<p data-end=\"556\" data-start=\"231\">Step into the colorful, nostalgic world of <strong data-end=\"298\" data-start=\"274\">Cereal Cash Candles</strong>! These highly scented soy candles don’t just smell incredible — they turn every burn into a fun, eye-catching experience. Each candle is hand-poured into a <strong data-end=\"475\" data-start=\"455\">real cereal bowl</strong> and comes with a <strong data-end=\"514\" data-start=\"493\">real spoon inside</strong>, making it as charming as it is fragrant.</p>\n<p data-end=\"871\" data-start=\"558\">Our 16-ounce, double-wicked candles burn smoothly for <strong data-end=\"625\" data-start=\"612\">80+ hours</strong>, filling your space with bold, delicious cereal-inspired aromas. Even the “milk” wax changes color depending on the scent — chocolate scents feature warm brown wax, fruity blends get playful pastel tones, and every bowl looks good enough to eat.</p>\n<hr data-end=\"876\" data-start=\"873\">\n<h3 data-end=\"929\" data-start=\"878\"><strong data-end=\"929\" data-start=\"882\">What Makes Cereal Cash Candles So Exciting?</strong></h3>\n<ul data-end=\"1412\" data-start=\"931\">\n<li data-end=\"1108\" data-start=\"931\">\n<p data-end=\"1108\" data-start=\"933\"><strong data-end=\"966\" data-start=\"933\">Real Cash Inside Every Candle</strong><br data-end=\"969\" data-start=\"966\">Each candle includes a guaranteed real <strong data-end=\"1021\" data-start=\"1010\">$2 bill</strong>, and <strong data-end=\"1064\" data-start=\"1027\">some candles are packed at random</strong> with bonus cash surprises up to <strong data-end=\"1107\" data-start=\"1097\">$2,500</strong>.</p>\n</li>\n<li data-end=\"1276\" data-start=\"1110\">\n<p data-end=\"1276\" data-start=\"1112\"><strong data-end=\"1141\" data-start=\"1112\">Tons of Incredible Scents</strong><br data-end=\"1144\" data-start=\"1141\">From fruity classics to chocolatey treats and nostalgic favorites, there’s a <strong data-end=\"1240\" data-start=\"1223\">cereal candle</strong> for every vibe and every gift list.</p>\n</li>\n<li data-end=\"1412\" data-start=\"1278\">\n<p data-end=\"1412\" data-start=\"1280\"><strong data-end=\"1315\" data-start=\"1280\">Clean, Eco-Friendly Ingredients</strong><br data-end=\"1318\" data-start=\"1315\">Our soy wax and cotton wicks deliver a clean, long-lasting burn with room-filling fragrance.</p>\n</li>\n</ul>",
