    "title": "Cash Bath Bombs Tubes (2-PACK BUNDLES)",
    "description": "<p>Upgrade your bath routine with our <strong>Cash Bath Bomb Tube Bundles</strong>—extra-large, luxury bath bombs that turn every soak into an unforgettable experience.</p>\n<p>Each bundle includes <strong>two GIANT bath bombs</strong>, each weighing <strong>7.5 ounces</strong> and packed with bold fragrance, rich fizz, and silky skin-softening ingredients. These are not ordinary bath bombs. They are oversized, highly fragrant, and designed to deliver a spa-quality soak at home.</p>\n<p>Every bath bomb contains a <strong>REAL $2 bill</strong>, and <strong>RANDOMIZED bundles</strong> include additional cash rewards up to <strong>$2,500</strong>, making each bath both relaxing and exciting. Drop one in the tub and enjoy the thrill of a surprise reveal as the bomb fizzes and colors the water.</p>\n<p>Our cash bath bombs are crafted with <strong>skin-safe, high-quality ingredients</strong> including food-grade baking soda and citric acid, coconut oil for moisture, sea salt for relaxation, and premium essential and fragrance oils. The result is soft skin, a smooth soak, and an amazing scent experience—without harsh chemicals.</p>\n<p>Available in a wide variety of best-selling scents, our <strong>money bath bombs</strong> are perfect for gifting, self-care nights, birthdays, holidays, and anyone who loves fun, luxury, and surprises. Big size. Big scent. Big excitement.</p>\n<p>Shop our <strong>Cash Bath Bomb Tube Bundles</strong> now and discover why these oversized bath bombs are one of the most talked-about bath experiences online—where luxury bathing meets the thrill of <strong>RANDOM cash surprises</strong>.</p>",
