    "referenceCount": 20,
    "actualCount": 20,
    "title": "Jewelry Sugar Scrubs",
    "description": "<p data-mce-fragment=\"1\">Scrub-a-dub-dub! Say hello to you bath’s new best friend—our scented sugar scrubs! Made in the USA with ethically-sourced ingredients, each of our jewelry sugar scrubs are the perfect pick-me-up when you need a day of pampering and relaxation. Plus, each of our scented sugar scrubs come with a special piece of jewelry inside valued from $10 to $7500. Once you’ve discovered your hidden jewelry, you can use our online free appraising program to find out exactly how much your prize is worth.</p>\n<p data-mce-fragment=\"1\">With the potential to find diamonds, cash, and even real gold, our unique 2-in-1 products add a fun twist to your time in the tub while still ensuring that your skin is treated with healthy ingredients that will result in an all-over glow.</p>\n<p data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">Beautiful Scents to Fit Every Mood</strong></p>\n<div class=\"medium-up--one-half grid__item\" data-mce-fragment=\"1\">\n<p data-mce-fragment=\"1\">Our scented sugar scrubs are available in 15 unique scents that are made to please every customer. Our<span data-mce-fragment=\"1\"> </span><a href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/flirty-little-secret-jewelry-sugar-scrub\" data-mce-fragment=\"1\" data-mce-href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/flirty-little-secret-jewelry-sugar-scrub\" target=\"_blank\">Flirty Little Secret Jewelry Sugar Scrub</a>, one of our best sellers, has hints of warm vanilla and tropical coconut that will soothe your tired mind and body, while the<span data-mce-fragment=\"1\"> </span><a href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/bombshell-jewelry-sugar-scrub\" data-mce-fragment=\"1\" data-mce-href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/bombshell-jewelry-sugar-scrub\" target=\"_blank\">Bombshell Jewelry Sugar Scrub</a><span data-mce-fragment=\"1\"> </span>has exhilarating tones of red berry and golden amber that will awaken your senses. Our<span data-mce-fragment=\"1\"> </span><a href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/seduction-jewelry-sugar-scrub\" data-mce-fragment=\"1\" data-mce-href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/seduction-jewelry-sugar-scrub\" target=\"_blank\">Seduction Jewelry Sugar Scrub</a><span data-mce-fragment=\"1\"> </span>will fully prepare you for a night in, while the<span data-mce-fragment=\"1\"> </span><a href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/tiki-party-jewelry-sugar-scrub\" data-mce-fragment=\"1\" data-mce-href=\"https://www.jewelrycandles.com/collections/jewelry-sugar-scrubs/products/tiki-party-jewelry-sugar-scrub\" target=\"_blank\">Tiki Party Jewelry Sugar Scrub</a><span data-mce-fragment=\"1\"> </span>will have you ready to dance the night away.</p>\n<p data-mce-fragment=\"1\">In addition to addicting scents, our scented sugar scrubs are made with all-natural essential oils that are guaranteed to be skin safe and toxic free. We strive to make products that are kind to our environment, so all of our jewelry scrubs are cruelty-free and vegan-friendly. Our scented sugar scrubs are specially crafted to give you the unique sparkle that you can only find with Jewelry Candles products. With high-quality ingredients, uplifting scents, and a hidden gift in every box there is no reason not to buy one of our addicting jewelry scrubs.</p>\n</div>\n<div class=\"medium-up--one-half grid__item\" data-mce-fragment=\"1\">Shop Our Jewelry Sugar Scrubs at Jewelry Candles At Jewelry Candles, it is our mission to provide our customers with exciting products that actually work. With our scented sugar scrubs, our customers are getting the best combination of healthy skin ingredients and stunning surprise jewelry that will amp up your time in the bath. The sugar scrubs perfectly exfoliate your skin while simultaneously filling your senses with decadent aromas.\n<p data-mce-fragment=\"1\">The essential oils and other naturally derived ingredients will help to calm your mind as you scrub away the day’s stresses, and the hidden jewelry inside every box will only add to your excitement about these fun products. Whether you’re looking to treat yourself or you’re on the hunt for the perfect gift for a friend, our jewelry sugar scrubs have something for everyone. Soak in the luxury and let the day’s worries melt away—find your perfect jewelry sugar scrub at Jewelry Candles today!</p>\n</div>",
