    "description": "<p>**Money Bath Salts**: Indulge in a bath like no other with our *Money Bath Salts*, each featuring a guaranteed real $2 bill, all in a lovely reusable 21-ounce plastic container. Plus, some random containers hold up to an additional $2,500 in cash! Our bath salts come in a variety of luxurious scents made with skin-safe essential oils, ensuring a soothing and aromatic experience. We use only the best ingredients, including skin-safe magnesium sulfate (Epsom salt), organic aloe vera gel, and organic coconut oil to nourish and moisturize your skin. Treat yourself to the ultimate bath experience and the chance to win big!</p>\n<p>**Warning**: For external use only. Keep out of reach of children. Avoid contact with eyes. If irritation occurs, discontinue use and consult a physician. Not intended for consumption. Use caution when entering or exiting the bath, as oils may cause surfaces to become slippery. Do not use if allergic to any ingredients listed.</p>",
