    "referenceCount": 29,
    "actualCount": 28,
    "title": "Cash Candy",
    "description": "<p data-start=\"110\" data-end=\"248\">Inspired by the magic and whimsy of <em data-start=\"146\" data-end=\"181\">Charlie and the Chocolate Factory</em>, we’re excited to introduce our all-new <strong data-start=\"222\" data-end=\"247\">Cash Candy Collection</strong>.</p>\n<p data-start=\"250\" data-end=\"453\">So what is Cash Candy? Each Cash Candy tube is filled with <strong data-start=\"309\" data-end=\"354\">over half a pound of mouth-watering candy</strong>, sealed inside a fun, collectible tube — and <strong data-start=\"400\" data-end=\"452\">every single tube includes a REAL $2 bill inside</strong>.</p>\n<p data-start=\"455\" data-end=\"693\">To make it even more special, <strong data-start=\"485\" data-end=\"547\">you can select the type of candy you want inside your tube</strong> from a variety of popular favorites listed in our dropdown menu. This makes Cash Candy a <strong data-start=\"637\" data-end=\"658\">personalized gift</strong> that’s as thoughtful as it is fun.</p>\n<p data-start=\"695\" data-end=\"842\">And for extra excitement, <strong data-start=\"721\" data-end=\"787\">random tubes can include an additional cash prize up to $2,500</strong>, placed inside at total random. <strong data-start=\"820\" data-end=\"842\">No odds are given.</strong></p>\n<p data-start=\"844\" data-end=\"958\">Every Cash Candy tube is a novelty product, created purely for enjoyment — sweet, playful, and unforgettable. 🍬💵</p>",
