    "title": "Jewelry Candy",
    "description": "<p data-start=\"217\" data-end=\"407\">Inspired by the magic and imagination of <em data-start=\"258\" data-end=\"293\">Charlie and the Chocolate Factory</em>, we’re excited to introduce our all-new <strong data-start=\"334\" data-end=\"362\">Jewelry Candy Collection</strong> — where sweet treats meet a surprise inside.</p>\n<p data-start=\"409\" data-end=\"617\">So what is Jewelry Candy? Each Jewelry Candy tube is filled with <strong data-start=\"474\" data-end=\"523\">over half a pound of delicious assorted candy</strong>, sealed inside a fun, collectible tube — along with a <strong data-start=\"578\" data-end=\"616\">jewelry surprise inside every tube</strong>.</p>\n<p data-start=\"619\" data-end=\"860\">To make it even more special, <strong data-start=\"649\" data-end=\"723\">you can select both the type of candy and the type of jewelry you want</strong> from popular options listed in our dropdown menus. This lets you create a <strong data-start=\"798\" data-end=\"825\">fully personalized gift</strong> that’s as thoughtful as it is fun.</p>\n<p data-start=\"862\" data-end=\"1072\">Every Jewelry Candy tube includes <strong data-start=\"896\" data-end=\"935\">jewelry with a minimum value of $15</strong>, and <strong data-start=\"941\" data-end=\"1017\">random tubes can include an additional jewelry piece valued up to $7,500</strong>, placed inside at total random. <strong data-start=\"1050\" data-end=\"1072\">No odds are given.</strong></p>\n<p data-start=\"1074\" data-end=\"1221\">Jewelry Candy is a novelty product created purely for enjoyment — perfect for birthdays, holidays, or anyone who loves candy with a surprise twist.</p>\n<p data-start=\"1223\" data-end=\"1318\">Sweet, customizable, and unforgettable — <strong data-start=\"1264\" data-end=\"1313\">Jewelry Candy is candy with a sparkle inside.</strong> </p>",
