    "referenceCount": 28,
    "actualCount": 28,
    "title": "Jewelry Chocolates",
    "description": "<p data-start=\"161\" data-end=\"359\">Inspired by the magic and imagination of <em data-start=\"202\" data-end=\"237\">Charlie and the Chocolate Factory</em>, we’re excited to introduce our all-new <strong data-start=\"278\" data-end=\"311\">Jewelry Chocolates Collection</strong> — where rich chocolate meets a surprise inside.</p>\n<p data-start=\"361\" data-end=\"584\">So what are Jewelry Chocolates? Each Jewelry Chocolate tube is filled with <strong data-start=\"436\" data-end=\"490\">over half a pound of delicious assorted chocolates</strong>, sealed inside a fun, collectible tube — along with a <strong data-start=\"545\" data-end=\"583\">jewelry surprise inside every tube</strong>.</p>\n<p data-start=\"586\" data-end=\"851\">To make it even more special, <strong data-start=\"616\" data-end=\"695\">you can select both the type of chocolates and the type of jewelry you want</strong> from popular options listed in our dropdown menus. This allows you to create a <strong data-start=\"775\" data-end=\"802\">fully personalized gift</strong> that’s indulgent, thoughtful, and one of a kind.</p>\n<p data-start=\"853\" data-end=\"1067\">Every Jewelry Chocolate tube includes <strong data-start=\"891\" data-end=\"930\">jewelry with a minimum value of $15</strong>, and <strong data-start=\"936\" data-end=\"1012\">random tubes can include an additional jewelry piece valued up to $7,500</strong>, placed inside at total random. <strong data-start=\"1045\" data-end=\"1067\">No odds are given.</strong></p>\n<p data-start=\"1069\" data-end=\"1196\">Jewelry Chocolates are a novelty product created purely for enjoyment — perfect for gifting, celebrating, or treating yourself.</p>\n<p data-start=\"1198\" data-end=\"1317\">Decadent, customizable, and unforgettable — <strong data-start=\"1242\" data-end=\"1312\">Jewelry Chocolates are more than chocolate… they’re an experience.</strong></p>",
