/**
 * Fast lookup map from any handle or alias (case-insensitive) to the authoritative collection meta.
 */
const aliasToCanonical = new Map<string, ApprovedCollectionMeta>();

Object.values(APPROVED_COLLECTIONS_MAP).forEach((col) => {
  aliasToCanonical.set(col.canonicalHandle.toLowerCase(), col);
});

Object.values(APPROVED_COLLECTIONS_MAP).forEach((col) => {
  col.aliases.forEach((alias) => {
    if (!aliasToCanonical.has(alias.toLowerCase())) {
      aliasToCanonical.set(alias.toLowerCase(), col);
    }
  });
});

export function getApprovedCollectionMeta(handleOrSlug: string): ApprovedCollectionMeta | null {
  if (!handleOrSlug) return null;
  const clean = decodeURIComponent(handleOrSlug).trim().toLowerCase();
  return aliasToCanonical.get(clean) || null;
}
